import{_ as a,C as n,o as r,c as i,aj as e,E as o}from"./framework.js";const k=JSON.parse('{"title":"SQL Logs | Database | Admin CMS","description":"SQL logs show SQL statements executed by site scripts through k.DB.sqlite / k.DB.mysql / k.DB.sqlServer: statement text, parameters, duration, and database type for troubleshooting and…","frontmatter":{"title":"SQL Logs | Database | Admin CMS","description":"SQL logs show SQL statements executed by site scripts through k.DB.sqlite / k.DB.mysql / k.DB.sqlServer: statement text, parameters, duration, and database type for troubleshooting and…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/database/sql-logs.html"}]]},"headers":[],"relativePath":"cms/database/sql-logs.md","filePath":"en/cms/database/sql-logs.md","lastUpdated":1781010536000}'),d={name:"cms/database/sql-logs.md"};function l(g,t,h,c,p,b){const s=n("DocImage");return r(),i("div",null,[t[0]||(t[0]=e('<h1 id="sql-logs" tabindex="-1">SQL Logs <a class="header-anchor" href="#sql-logs" aria-label="Permalink to &quot;SQL Logs&quot;">​</a></h1><blockquote><p>Menu: <strong>Database → SQL Logs</strong><br> Deep link: <code>/_Admin/database/sql-logs?SiteId={siteGuid}</code></p></blockquote><p><strong>SQL logs</strong> show SQL statements executed by site scripts through <strong><code>k.DB.sqlite</code> / <code>k.DB.mysql</code> / <code>k.DB.sqlServer</code></strong>: statement text, parameters, duration, and database type for troubleshooting and auditing. This page is <strong>read-only</strong> observation; it does not delete or edit logs, and there is no corresponding <code>k.*</code> write API.</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><p>Viewing this page and list data: <code>database·log</code> (the <strong>log</strong> action on the <code>database</code> feature).<br> The <strong>Enable</strong> toggle on the toolbar right saves site settings and usually requires site <strong>edit</strong>-class permissions (same as saving site configuration).</p></div><div class="warning custom-block"><p class="custom-block-title">What is logged</p><table tabindex="0"><thead><tr><th>Logged</th><th>Not logged</th></tr></thead><tbody><tr><td>SQL from <code>k.DB.sqlite.query</code> / <code>execute</code>, etc.</td><td><a href="./table.html">IndexedDB tables</a> (<code>k.DB.indexedDb</code>) operations</td></tr><tr><td>SQL from <code>k.DB.mysql</code>, <code>k.DB.sqlServer</code></td><td><a href="./key-value.html">Key-value storage</a> (<code>k.DB.keyValue</code>)</td></tr><tr><td>SQL from admin <strong>SQLite / MySQL / SQL Server</strong> maintenance when routed through the same executor (if applicable)</td><td>Any SQL when <strong>SQL logging</strong> is disabled</td></tr></tbody></table><p>You must enable <strong>SQL logging</strong> on the site first (see <a href="#enable-sql-logging">Enable SQL logging</a>); only SQL produced after that is written to the log.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, check <strong>Database → SQL Logs</strong>.</li><li>Open <strong>Database → SQL Logs</strong> in the left sidebar.</li></ol>',7)),o(s,{src:"/cms/database/sql-logs-overview.png",alt:"SQL logs page",width:"1120"}),t[1]||(t[1]=e('<h2 id="enable-sql-logging" tabindex="-1">Enable SQL logging <a class="header-anchor" href="#enable-sql-logging" aria-label="Permalink to &quot;Enable SQL logging&quot;">​</a></h2><p>Site-level switch <strong><code>enableSqlLog</code></strong>; both locations are equivalent (changing one is enough):</p><table tabindex="0"><thead><tr><th>Location</th><th>Path</th></tr></thead><tbody><tr><td><strong>This page toolbar</strong></td><td><strong>Enable</strong> toggle on the right; saves the site immediately</td></tr><tr><td><strong>Site settings → Advanced</strong></td><td><code>/_Admin/system/settings?SiteId={siteGuid}&amp;name=advance</code>, <strong>SQL logging</strong> item</td></tr></tbody></table><p>When disabled, new script SQL is <strong>not</strong> written to the log; existing historical weekly data can still be viewed by week.</p>',4)),o(s,{src:"/cms/database/sql-logs-toolbar.png",alt:"SQL logs filters and enable toggle",width:"1120"}),t[2]||(t[2]=e('<h2 id="filters-and-search" tabindex="-1">Filters and search <a class="header-anchor" href="#filters-and-search" aria-label="Permalink to &quot;Filters and search&quot;">​</a></h2><p>Toolbar left to right:</p><table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td><strong>Week</strong></td><td>Select log file by <strong>calendar week</strong>; option text is <code>yyyy-MM-dd~yyyy-MM-dd</code> (week start/end). Only weeks where <strong>the current site has entries</strong> are listed; if none yet, defaults to <strong>current week</strong></td></tr><tr><td><strong>Type</strong></td><td>Optional <strong>SQLite</strong>, <strong>MySQL</strong>, <strong>SQLServer</strong> (maps to <code>sqlite</code> / <code>mysql</code> / <code>sqlserver</code>); clear for all types</td></tr><tr><td><strong>Keyword</strong></td><td>Fuzzy match in <strong>SQL body</strong> (case-insensitive); ~1 second debounce after input; clear to refresh</td></tr><tr><td><strong>Enable</strong></td><td>See <a href="#enable-sql-logging">Enable SQL logging</a></td></tr></tbody></table><p>Changing <strong>Week</strong>, <strong>Type</strong>, or keyword re-requests <code>SqlLog/List</code> and returns to page 1.</p><h2 id="log-list" tabindex="-1">Log list <a class="header-anchor" href="#log-list" aria-label="Permalink to &quot;Log list&quot;">​</a></h2><p>Default pagination <strong>50</strong> rows per page (<code>KTable</code> pagination at bottom).</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>Database source, e.g. <code>sqlite</code>, <code>mysql</code>, <code>sqlserver</code></td></tr><tr><td><strong>Date time</strong></td><td>Execution time (site timezone)</td></tr><tr><td><strong>Execution time</strong></td><td>Duration in <strong>ms</strong></td></tr><tr><td><strong>Content</strong></td><td>SQL statement summary (truncated in table when long)</td></tr><tr><td><strong>Parameters</strong></td><td>Serialized parameter object; empty when none or <code>null</code></td></tr><tr><td>Row <strong>Details</strong></td><td>Opens <a href="#details-dialog">details dialog</a> when data exists</td></tr></tbody></table><p>When the week has no records, the table shows <strong>No data</strong> (logging must be <strong>enabled</strong> and the site must have executed <code>k.DB.sqlite</code> etc.).</p>',8)),o(s,{src:"/cms/database/sql-logs-list.png",alt:"SQL log list",width:"1120"}),t[3]||(t[3]=e(`<h3 id="details-dialog" tabindex="-1">Details dialog <a class="header-anchor" href="#details-dialog" aria-label="Permalink to &quot;Details dialog&quot;">​</a></h3><p>Click the row <strong>eye</strong> icon. Shows full <strong>Type</strong>, <strong>Date time</strong>, <strong>Execution time</strong>, and two full text blocks:</p><ol><li><strong>SQL statement</strong> (with line breaks)</li><li><strong>Parameters</strong> (JSON or other serialized form)</li></ol><p>Use to copy the full statement or compare parameters in slow-query scenarios.</p><h2 id="how-logs-are-produced" tabindex="-1">How logs are produced <a class="header-anchor" href="#how-logs-are-produced" aria-label="Permalink to &quot;How logs are produced&quot;">​</a></h2><p>When scripts access relational databases and <code>EnableSqlLog</code> is true, the executor asynchronously writes to server log files partitioned by <strong>week</strong> (under site <code>AppData</code> <code>SqlLog</code>, filenames like <code>{yearWeek}.log</code>). Writes and list queries filter by <strong>site ID</strong>; you only see this site’s records.</p><p>Example (after logging is enabled):</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.sqlite.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SELECT * FROM logs WHERE id = @id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { id: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.sqlite.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;INSERT INTO logs (msg) VALUES (@msg)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { msg: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>For MySQL / SQL Server, configure connections under <a href="./../navigation.html">Service integrations</a> (<code>/system/config</code>), then execute via <code>k.DB.mysql</code> / <code>k.DB.sqlServer</code> to see logs of the matching <strong>type</strong>.</p><div class="info custom-block"><p class="custom-block-title">Admin table maintenance</p><p>Whether <a href="./sqlite-table.html">SQLite tables</a> list/column/data <strong>admin APIs</strong> share the same execution chain as script <code>k.DB.sqlite</code> depends on the environment. When troubleshooting script SQL, rely on <strong>Type</strong> and <strong>Content</strong> on this page; if admin actions produce no log, confirm execution goes through <code>k.DB.*</code> and logging is <strong>enabled</strong>.</p></div><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical workflow&quot;">​</a></h2><ol><li>Turn on <strong>SQL logging</strong> under <strong>Advanced</strong> or on this page.</li><li>Reproduce the issue (page or job that runs <code>k.DB.sqlite</code>, etc.).</li><li>Select the <strong>week</strong>, narrow by <strong>type</strong> / <strong>keyword</strong>.</li><li>Open <strong>Details</strong>, copy SQL and parameters, verify in Code or a database tool.</li><li>Long-term enablement in production may increase I/O and disk use; turn off <strong>Enable</strong> after troubleshooting.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./">Database overview</a></td><td>Menus and permissions</td></tr><tr><td><a href="./sqlite-table.html">SQLite tables</a></td><td>Built-in SQLite and CSV</td></tr><tr><td><a href="/kb-docs/api/sqlite/">k.DB.sqlite</a></td><td>Script SQL API</td></tr><tr><td><a href="/kb-docs/api/database/">k.DB</a></td><td>Database overview</td></tr></tbody></table>`,14))])}const m=a(d,[["render",l]]);export{k as __pageData,m as default};
